e=next(x for x in json.loads((R/'P54_B_ASSIGNMENT_PRIVATE_V1.json').read_text())['entries']if x['id']==id);pr=next(x for x in json.loads((R/'P54_B_GENERATION_PROMPTS_PRIVATE_V1.json').read_text())['entries']if x['id']==id)
