im=Image.open(dst).convert('RGBA');a=im.getchannel('A');box=a.point(lambda x:255 if x>=16 else 0).getbbox();assert box;w,h=im.size;l,t,rr,bb=box;cid='original--'+id.lower()+'-'+SLUGS[id]
p={'schema':'cqc.p54.single-static-original-proposal/1','atUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'id':id,'uid':e['uid'],'character':e['character'],'costumeName':e['name'],'costumeID':cid,'family':e['family'],'canon':False,'isOriginalCQC':True,'historicalLostExpectedSHA256':e['sha256'],'historicalSourceRecovered':False,'newVersionProduction':True,'rawPNG':{'path':str(dst),'generatorOutputPath':str(src),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'width':w,'height':h},'prompt':pr,'slots':[{'uid':e['uid'],'costumeID':cid,'classification':'original-cqc-static-pose','sourceRect':[l,t,rr-l,bb-t],'bodyBounds':[l,t,rr-l,bb-t],'bodyDatumX':(l+rr)/2,'footDatumY':bb-1,'facing':'right','poseCount':1,'animationCount':0}],'referenceSources':[x for x in [e.get('sourceReference'),e.get('familyReference')]if x],'visualReview':{'physicallyViewed':True,'oneFigure':True,'fullBodyWithinFrame':True,'facingRight':True,'description':DESCRIPTIONS[id],'note':args.note,'limits':'Original CQC design; no claim of official outfit or exact recovered historical pixels. Anchor is preliminary and may be refined in catalogue QA.'},'alphaQA':{'bboxAtAlpha16':[l,t,rr,bb],'cornerAlpha':[a.getpixel(x)for x in[(0,0),(w-1,0),(0,h-1),(w-1,h-1)]],'alphaExtrema':a.getextrema()},'newAnimations':0,'runtimeAdmission':False}
